{
    int x, n;
    scanf("%d %d", &x, &n);
    printf("%d\n", power(x, n));
    return 0;
}

#include <stdio.h>

int maxOfArray(int a[], int n)
{
    int i, m = a[0];
    for (i = 1; i < n; i++)
        if (a[i] > m)
            m = a[i];
    return m;
}

int main()
{
    int n, i, a[100], m, pos = 0;
    scanf("%d", &n);
    for (i = 0; i < n; i++)
        scanf("%d", &a[i]);
    m = maxOfArray(a, n);
    for (i = 0; i < n; i++)
        if (a[i] == m)
        {
            pos = i;
            break;
        }
    printf("%d\n", m);
    printf("%d\n", pos);
    return 0;
}

