#include <stdio.h>

int isPrime(int n)
{
    int j;
    if (n < 2)
        return 0;
    for (j = 2; j * j <= n; j++)
        if (n % j == 0)
            return 0;
    return 1;
}

int main()
{
    int n, i, first = 1;
    scanf("%d", &n);
    for (i = 2; i <= n; i++)
        if (isPrime(i))
        {
            if (!first)
                printf(" ");
            printf("%d", i);
            first = 0;
        }
    printf("\n");
    return 0;
}

#include <stdio.h>

void swap1(int x, int y)
{
    int t;
    t = x;
    x = y;
    y = t;
}

void swap2(int *x, int *y)
{
    int t;
    t = *x;
    *x = *y;
    *y = t;
}

int main()
{
    int a, b;
    scanf("%d%d", &a, &b);
    swap1(a, b);
    printf("%d %d\n", a, b);
    swap2(&a, &b);
    printf("%d %d\n", a, b);
    return 0;
}

#include <stdio.h>

void factor(int n)
{
    int i, first = 1, m = n;
    printf("%d=", n);
    for (i = 2; i <= m; i++)
        while (m % i == 0)
        {
            if (!first)
                printf("*");
            printf("%d", i);
            first = 0;
            m = m / i;
        }
    printf("\n");
}

int main()
{
    int n;
    scanf("%d", &n);
    factor(n);
    return 0;
}

#include <stdio.h>

int reverse(int n)
{
    int r = 0;
    while (n > 0)
    {
        r = r * 10 + n % 10;
        n = n / 10;
    }
    return r;
}

int main()
{
    int m;
    scanf("%d", &m);
    if (reverse(m) == m)
        printf("yes\n");
    else
        printf("no\n");
    return 0;
}
